const adminState={session:null,products:[],selected:null,removedVariantIds:[]};
const $=selector=>document.querySelector(selector);
const adminHeaders=()=>({apikey:ALMEIDA_SUPABASE_KEY,Authorization:'Bearer '+adminState.session.access_token});
const money=cents=>(Number(cents||0)/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const escapeHtml=value=>{const node=document.createElement('div');node.textContent=value??'';return node.innerHTML};
const message=(text,error=false)=>{const target=$('#login-message');target.textContent=text;target.classList.toggle('error',error)};
async function request(path,options={}){const response=await fetch(ALMEIDA_SUPABASE_URL+path,{...options,headers:{...adminHeaders(),...(options.headers||{})}});const body=await response.text();let data=null;if(body){try{data=JSON.parse(body)}catch{data={message:body}}}if(!response.ok)throw new Error(data?.message||data?.error||`Não foi possível concluir (${response.status}).`);return data}
async function signIn(email,password){const response=await fetch(ALMEIDA_SUPABASE_URL+'/auth/v1/token?grant_type=password',{method:'POST',headers:{apikey:ALMEIDA_SUPABASE_KEY,'Content-Type':'application/json'},body:JSON.stringify({email,password})});const data=await response.json();if(!response.ok)throw new Error(data.error_description||'E-mail ou senha não conferem.');return data}
async function isAdmin(session){const user=await fetch(ALMEIDA_SUPABASE_URL+'/auth/v1/user',{headers:{apikey:ALMEIDA_SUPABASE_KEY,Authorization:'Bearer '+session.access_token}});if(!user.ok)return false;const profile=await request('/rest/v1/profiles?select=role&id=eq.'+encodeURIComponent((await user.json()).id));return profile[0]?.role==='admin'}
async function openPanel(session){adminState.session=session;try{if(!await isAdmin(session))throw new Error('Este e-mail ainda não tem autorização para acessar o painel da loja.');sessionStorage.setItem('almeida-admin-session',JSON.stringify(session));$('#admin-login').hidden=true;$('#admin-panel').hidden=false;await loadProducts()}catch(error){adminState.session=null;sessionStorage.removeItem('almeida-admin-session');message(error.message,true)}}
async function loadProducts(){const select='id,brand,name,subcategory,description,image_url,image_override_url,active,product_variants(id,name,price_cents,stock_quantity,active)';adminState.products=await request('/rest/v1/products?select='+encodeURIComponent(select)+'&order=name.asc');renderList();if(adminState.selected){const fresh=adminState.products.find(item=>item.id===adminState.selected.id);if(fresh)selectProduct(fresh)}}
function renderList(){const term=$('#admin-search').value.trim().toLocaleLowerCase('pt-BR');const list=adminState.products.filter(product=>(product.brand+' '+product.name).toLocaleLowerCase('pt-BR').includes(term));$('#admin-products').innerHTML=list.map(product=>`<button type="button" class="admin-product ${product.id===adminState.selected?.id?'selected':''}" data-id="${product.id}"><span class="admin-dot ${product.active?'':'off'}"></span><span><b>${escapeHtml(product.name)}</b><small>${escapeHtml(product.brand)} · ${product.product_variants.length} variações</small></span></button>`).join('')||'<p class="admin-empty-list">Nenhum produto encontrado.</p>'}
const naturalVariantOrder=(a,b)=>String(a.name).localeCompare(String(b.name),'pt-BR',{numeric:true,sensitivity:'base'});
function selectProduct(product){adminState.selected=product;adminState.removedVariantIds=[];product={...product,product_variants:(product.product_variants||[]).filter(v=>v.active).sort(naturalVariantOrder)};renderList();$('#editor-empty').hidden=true;const form=$('#product-editor');form.hidden=false;const currentImage=product.image_override_url||(typeof localProductImage==='function'&&localProductImage(product.brand,product.name,product.image_url));const categories=[...new Set(adminState.products.map(item=>item.subcategory).filter(Boolean))];if(!categories.includes(product.subcategory))categories.push(product.subcategory);categories.sort((a,b)=>a.localeCompare(b,'pt-BR',{sensitivity:'base'}));form.innerHTML=`<div class="editor-title"><div><small>EDITANDO PRODUTO</small><h2>${escapeHtml(product.name)}</h2></div><label class="availability"><input id="product-active" type="checkbox" ${product.active?'checked':''}> Exibir no catálogo</label></div><div class="editor-grid"><label>Marca<input id="product-brand" required value="${escapeHtml(product.brand)}"></label><label>Nome do produto<input id="product-name" required value="${escapeHtml(product.name)}"></label><label>Categoria<select id="product-category" required>${categories.map(category=>`<option value="${escapeHtml(category)}" ${category===product.subcategory?'selected':''}>${escapeHtml(category)}</option>`).join('')}</select></label></div><label>Descrição<textarea id="product-description" rows="5" placeholder="Descrição que aparecerá na página do produto">${escapeHtml(product.description||'')}</textarea></label><section class="photo-editor"><div><b>Foto do produto</b><p>Envie uma foto em JPG, PNG ou WebP. Ela passa a ser usada no card e na página do produto.</p><input id="product-image" type="file" accept="image/jpeg,image/png,image/webp"></div>${currentImage?`<img src="${escapeHtml(currentImage)}" alt="Foto atual de ${escapeHtml(product.name)}">`:'<div class="admin-photo-placeholder">Sem foto cadastrada</div>'}</section><section class="variants-editor"><div class="variants-heading"><div><b>Variações e preços</b><p>Preço em reais. Deixe uma variação inativa para ocultá-la sem apagar o histórico.</p></div><button id="add-variant" type="button" class="secondary">Adicionar variação</button></div><div id="variant-rows">${product.product_variants.map(variantRow).join('')}</div></section><button class="primary" type="submit">Salvar alterações</button><p id="editor-message" class="admin-message" aria-live="polite"></p>`;form.querySelector('#add-variant').onclick=()=>{form.querySelector('#variant-rows').insertAdjacentHTML('beforeend',variantRow({id:'',name:'',price_cents:0,stock_quantity:null,active:true}))};if(window.matchMedia('(max-width:800px)').matches)setTimeout(()=>form.scrollIntoView({behavior:'smooth',block:'start'}),0);}
function variantRow(variant){return `<div class="variant-row" data-id="${variant.id||''}"><label>Variação<input class="variant-name" required value="${escapeHtml(variant.name)}" placeholder="Ex.: 500 ml"></label><label>Preço (R$)<input class="variant-price" type="number" min="0" step="0.01" required value="${(Number(variant.price_cents||0)/100).toFixed(2)}"></label><label>Estoque<input class="variant-stock" type="number" min="0" step="1" value="${variant.stock_quantity??''}" placeholder="Opcional"></label><label class="availability"><input class="variant-active" type="checkbox" ${variant.active?'checked':''}> Ativa</label><button class="remove-variant" type="button" title="Remover variação" aria-label="Remover variação">×</button></div>`}
async function uploadPhoto(file,productId){if(!file)return null;if(file.size>6*1024*1024)throw new Error('A foto precisa ter no máximo 6 MB.');const extension=(file.name.split('.').pop()||'jpg').replace(/[^a-z0-9]/gi,'').toLowerCase();const path=productId+'/'+Date.now()+'.'+extension;const response=await fetch(ALMEIDA_SUPABASE_URL+'/storage/v1/object/product-images/'+path,{method:'POST',headers:{...adminHeaders(),'Content-Type':file.type||'application/octet-stream','x-upsert':'true'},body:file});if(!response.ok){let detail='';try{detail=(await response.json()).message||''}catch{}throw new Error(detail||'Não foi possível enviar a foto.')}return ALMEIDA_SUPABASE_URL+'/storage/v1/object/public/product-images/'+path}
[['show-login-password','login-password'],['show-signup-password','signup-password']].forEach(([toggle,input])=>{$('#'+toggle).onchange=event=>{$('#'+input).type=event.target.checked?'text':'password'}});
$('#login-form').addEventListener('submit',async event=>{event.preventDefault();message('Entrando...');try{await openPanel(await signIn($('#login-email').value.trim(),$('#login-password').value));message('')}catch(error){message(error.message,true)}});
$('#signup-form').addEventListener('submit',async event=>{event.preventDefault();message('Criando seu acesso...');try{const response=await fetch(ALMEIDA_SUPABASE_URL+'/auth/v1/signup',{method:'POST',headers:{apikey:ALMEIDA_SUPABASE_KEY,'Content-Type':'application/json'},body:JSON.stringify({email:$('#signup-email').value.trim(),password:$('#signup-password').value,data:{full_name:$('#signup-name').value.trim()}})});const data=await response.json();if(!response.ok)throw new Error(data.msg||data.message||'Não foi possível criar o acesso.');if(data.session)await openPanel(data.session);else message('Confira seu e-mail para confirmar o acesso e depois entre pelo formulário acima.')}catch(error){message(error.message,true)}});
$('#logout').onclick=async()=>{try{await request('/auth/v1/logout',{method:'POST'})}catch{}adminState.session=null;adminState.products=[];adminState.selected=null;sessionStorage.removeItem('almeida-admin-session');$('#admin-panel').hidden=true;$('#admin-login').hidden=false;message('Você saiu do painel.');};
$('#admin-search').oninput=renderList;
$('#admin-products').onclick=event=>{const button=event.target.closest('[data-id]');if(button)selectProduct(adminState.products.find(product=>product.id===button.dataset.id))};
$('#product-editor').addEventListener('click',event=>{const remove=event.target.closest('.remove-variant');if(remove){const row=remove.closest('.variant-row');const total=$('#variant-rows').querySelectorAll('.variant-row').length;if(total===1){$('#editor-message').textContent='Um produto precisa ter pelo menos uma variação.';return}if(row.dataset.id)adminState.removedVariantIds.push(row.dataset.id);row.remove()}});
$('#product-editor').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget, product=adminState.selected, note=$('#editor-message');note.className='admin-message';note.textContent='Salvando...';try{const imageUrl=await uploadPhoto($('#product-image').files[0],product.id);const update={brand:$('#product-brand').value.trim(),name:$('#product-name').value.trim(),subcategory:$('#product-category').value.trim(),description:$('#product-description').value.trim()||null,active:$('#product-active').checked};if(imageUrl)update.image_override_url=imageUrl;for(const removedId of adminState.removedVariantIds){await request('/rest/v1/product_variants?id=eq.'+encodeURIComponent(removedId),{method:'PATCH',headers:{'Content-Type':'application/json',Prefer:'return=minimal'},body:JSON.stringify({active:false})})}await request('/rest/v1/products?id=eq.'+encodeURIComponent(product.id),{method:'PATCH',headers:{'Content-Type':'application/json',Prefer:'return=minimal'},body:JSON.stringify(update)});for(const row of form.querySelectorAll('.variant-row')){const payload={product_id:product.id,name:row.querySelector('.variant-name').value.trim(),price_cents:Math.round(Number(row.querySelector('.variant-price').value)*100),stock_quantity:row.querySelector('.variant-stock').value===''?null:Math.max(0,Math.floor(Number(row.querySelector('.variant-stock').value))),active:row.querySelector('.variant-active').checked};if(!payload.name||Number.isNaN(payload.price_cents)||payload.price_cents<0)throw new Error('Preencha o nome e o preço de todas as variações.');const id=row.dataset.id;if(id)await request('/rest/v1/product_variants?id=eq.'+encodeURIComponent(id),{method:'PATCH',headers:{'Content-Type':'application/json',Prefer:'return=minimal'},body:JSON.stringify(payload)});else await request('/rest/v1/product_variants?on_conflict=product_id,name',{method:'POST',headers:{'Content-Type':'application/json',Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify(payload)})}note.textContent='Alterações salvas com sucesso.';await loadProducts()}catch(error){note.classList.add('error');note.textContent=error.message}});
document.addEventListener('focusin',event=>{const select=event.target.closest('#product-category');if(select&&!select.querySelector('option[value="__new_category__"]'))select.insertAdjacentHTML('beforeend','<option value="__new_category__">+ Criar nova categoria</option>')});
document.addEventListener('change',event=>{const select=event.target.closest('#product-category');if(!select||select.value!=='__new_category__')return;const name=window.prompt('Nome da nova categoria:')?.trim();if(!name){select.value=adminState.selected?.subcategory||'';return}const existing=[...select.options].find(option=>option.value===name);if(existing){select.value=name;return}const option=document.createElement('option');option.value=name;option.textContent=name;option.selected=true;select.insertBefore(option,select.lastElementChild)});
(async()=>{try{const saved=JSON.parse(sessionStorage.getItem('almeida-admin-session')||'null');if(saved?.access_token)await openPanel(saved)}catch{sessionStorage.removeItem('almeida-admin-session')}})();
